# Guards the generated dummy study variable dictionary.
#
# Two defects were found while building it: missing character values were
# rendered as the literal string "nan", and SAS date variables were leaked as
# epoch numbers because pandas decodes date-formatted columns to datetime64 and
# pd.to_numeric then converts them to nanoseconds. Both are cheap to re-check.
#
# The dictionary itself is generated by dummy_study/tools/build_variable_dictionary.py
# from the committed data and the committed SAS descriptor export.

dictionary_dir <- file.path(project_root, "dummy_study", "variables")
domains <- c(adsl = 49L, adae = 55L, adlbh = 46L)

read_dictionary <- function(domain) {
  readLines(file.path(dictionary_dir, paste0(domain, ".md")), warn = FALSE)
}

testthat::test_that("every dummy study dataset has a generated dictionary", {
  for (domain in names(domains)) {
    path <- file.path(dictionary_dir, paste0(domain, ".md"))
    testthat::expect_true(file.exists(path), label = paste("missing dictionary:", path))
  }
})

testthat::test_that("dictionary row counts match the declared variable counts", {
  for (domain in names(domains)) {
    text <- read_dictionary(domain)
    rows <- grep("^\\| [0-9]+ \\| ", text, value = TRUE)
    testthat::expect_equal(length(rows), domains[[domain]],
                           label = paste(domain, "variable rows"))
    testthat::expect_true(any(grepl(sprintf("变量数：\\*\\*%d\\*\\*", domains[[domain]]), text)),
                          label = paste(domain, "declared variable count"))
  }
})

testthat::test_that("missing character values are not reported as a value", {
  for (domain in names(domains)) {
    text <- paste(read_dictionary(domain), collapse = "\n")
    # A blank SAS character value must stay missing, not become the string "nan".
    testthat::expect_false(grepl("`nan`", text, fixed = TRUE),
                           label = paste(domain, "literal nan value"))
  }
})

testthat::test_that("date formatted variables are rendered as ISO dates", {
  text <- read_dictionary("adsl")
  trtsdt <- grep("^\\| [0-9]+ \\| TRTSDT \\|", text, value = TRUE)
  testthat::expect_length(trtsdt, 1L)
  # SAS reports TRTSDT as 09JUL2012 - 02SEP2014 through the DATE9 format; an
  # epoch leak would show a large integer instead.
  testthat::expect_match(trtsdt, "\\d{4}-\\d{2}-\\d{2} \u2013 \\d{4}-\\d{2}-\\d{2}")
})

testthat::test_that("the committed descriptor export covers all three datasets", {
  descriptors <- file.path(dictionary_dir, "descriptors.csv")
  testthat::expect_true(file.exists(descriptors))
  lines <- readLines(descriptors, warn = FALSE)
  testthat::expect_equal(length(lines) - 1L, sum(unlist(domains)),
                         label = "descriptor rows")
  testthat::expect_identical(lines[[1L]],
                             "domain,NAME,TYPE,LENGTH,VARNUM,LABEL,FORMAT,FORMATL,NOBS")
})
